{"content":"#!/usr/bin/env python3
"""Audit services/ against SPEC.md. Prints per-service evidence."""
import ast
import fnmatch
import json
import os
import re
import sys

ROOT = os.path.dirname(os.path.abspath(__file__))
SERVICES = os.path.join(ROOT, "services")
LFS_MAGIC = "version https://git-lfs.github.com/spec/v1"


def read(path):
    with open(path, "rb") as fh:
        return fh.read().decode("utf-8", "replace")


def is_pointer(path):
    try:
        with open(path, "rb") as fh:
            head = fh.readline().decode("utf-8", "replace").strip()
    except OSError:
        return False
    return head == LFS_MAGIC


def py_files(svc):
    out = []
    src = os.path.join(svc, "src")
    for dirpath, _dirs, files in os.walk(src):
        for name in files:
            if name.endswith(".py"):
                out.append(os.path.join(dirpath, name))
    return sorted(out)


def parse(path):
    return ast.parse(read(path), filename=path)


def handler_defs(tree):
    defs = []
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            defs.append(node)
    return defs


def has_docstring(fn):
    return ast.get_docstring(fn, clean=False) is not None


def check(svc_name):
    svc = os.path.join(SERVICES, svc_name)
    evidence = {}

    all_files = []
    for dirpath, _dirs, files in os.walk(svc):
        for name in files:
            all_files.append(os.path.join(dirpath, name))
    pointers = [os.path.relpath(p, svc) for p in all_files if is_pointer(p)]
    if pointers:
        return "unverifiable", [], {"pointers": sorted(pointers)}

    cfg = json.loads(read(os.path.join(svc, "config.json")))
    public = cfg.get("exposure") == "public"
    v = []

    # C1
    if public:
        t = cfg.get("timeout_s")
        if not (isinstance(t, (int, float)) and not isinstance(t, bool) and t <= 30):
            v.append("C1")
            evidence["C1"] = "timeout_s=%r" % (t,)

    # C2
    hpath = os.path.join(svc, "src", "handlers.py")
    htree = parse(hpath) if os.path.isfile(hpath) else None
    if htree is not None:
        missing = sorted(
            n.name for n in handler_defs(htree)
            if n.name.startswith("handle_") and not has_docstring(n)
        )
        if missing:
            v.append("C2")
            evidence["C2"] = missing

    # C3
    printed = []
    for p in py_files(svc):
        for node in ast.walk(parse(p)):
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) \
                    and node.func.id == "print":
                printed.append("%s:%d" % (os.path.relpath(p, svc), node.lineno))
    if printed:
        v.append("C3")
        evidence["C3"] = printed

    # C4
    r = cfg.get("retries")
    if not (isinstance(r, int) and not isinstance(r, bool) and 1 <= r <= 5):
        v.append("C4")
        evidence["C4"] = "retries=%r" % (r,)

    # C5
    dock = read(os.path.join(svc, "Dockerfile")).splitlines()
    froms = []
    for i, line in enumerate(dock, 1):
        s = line.strip()
        if not s or s.startswith("#"):
            continue
        if s.split()[0].upper() == "FROM":
            froms.append((i, s))
    bad_from = []
    for i, s in froms:
        parts = s.split()
        image = None
        for tok in parts[1:]:
            if tok.startswith("--"):
                continue
            image = tok
            break
        if image is None or not re.search(r"@sha256:[0-9a-f]{64}$", image):
            bad_from.append((i, image))
    if not froms or bad_from:
        v.append("C5")
        evidence["C5"] = bad_from or "no FROM line"

    # C6
    users = [s for s in dock if s.strip() and not s.strip().startswith("#")
             and s.strip().split()[0].upper() == "USER"]
    if not users:
        v.append("C6")
        evidence["C6"] = "no USER line"
    else:
        last = users[-1].strip().split(None, 1)[1].strip()
        uname = last.split()[0].split(":")[0]
        if uname in ("root", "0"):
            v.append("C6")
            evidence["C6"] = "last USER=%r" % last

    # C7
    readme = read(os.path.join(svc, "README.md")).splitlines()
    if "## Runbook" not in [ln.rstrip("\r") for ln in readme]:
        v.append("C7")
        evidence["C7"] = [ln for ln in readme if ln.strip().startswith("#")]

    # C8
    want = "@team-%s" % cfg.get("team")
    co = read(os.path.join(svc, "CODEOWNERS")).splitlines()
    star_ok = False
    star_rules = []
    for ln in co:
        s = ln.strip()
        if not s or s.startswith("#"):
            continue
        parts = s.split()
        if parts[0] == "*":
            star_rules.append(parts)
            if want in parts[1:]:
                star_ok = True
    if not star_ok:
        v.append("C8")
        evidence["C8"] = {"want": want, "star_rules": star_rules}

    # C9
    leaked = []
    for p in py_files(svc):
        for node in ast.walk(parse(p)):
            if isinstance(node, ast.Constant) and isinstance(node.value, str):
                if node.value.startswith("sk_live_") or node.value.startswith("AKIA"):
                    leaked.append("%s:%d" % (os.path.relpath(p, svc), node.lineno))
    if leaked:
        v.append("C9")
        evidence["C9"] = leaked

    # C10
    hc = cfg.get("healthcheck")
    if not (isinstance(hc, str) and hc.strip()):
        v.append("C10")
        evidence["C10"] = "healthcheck=%r" % (hc,)
    else:
        seg = hc.rstrip("/").split("/")[-1]
        hname = "handle_" + seg
        names = {n.name for n in handler_defs(htree)} if htree is not None else set()
        if hname not in names:
            v.append("C10")
            evidence["C10"] = {"healthcheck": hc, "missing": hname, "defined": sorted(names)}

    # C11
    if cfg.get("metrics_port") == cfg.get("port"):
        v.append("C11")
        evidence["C11"] = "port=%r metrics_port=%r" % (
            cfg.get("port"), cfg.get("metrics_port"))

    # C12
    req = read(os.path.join(svc, "requirements.txt")).splitlines()
    bad_req = []
    pat = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]*(\[[^\]]*\])?\s*==\s*[^=\s,;]+(\s*;\s*.+)?$")
    for ln in req:
        s = ln.strip()
        if not s or s.startswith("#"):
            continue
        body = re.sub(r"\s+#.*$", "", s).strip()
        if not pat.match(body):
            bad_req.append(s)
    if bad_req:
        v.append("C12")
        evidence["C12"] = bad_req

    # C13
    if cfg.get("log_level") == "DEBUG":
        v.append("C13")
        evidence["C13"] = cfg.get("log_level")

    # C14
    if public:
        b = cfg.get("max_body_kb")
        if not (isinstance(b, (int, float)) and not isinstance(b, bool) and b <= 1024):
            v.append("C14")
            evidence["C14"] = "max_body_kb=%r" % (b,)

    # C15
    tdir = os.path.join(svc, "tests")
    names = os.listdir(tdir) if os.path.isdir(tdir) else []
    ok = any(fnmatch.fnmatch(n, "test_*.py") and os.path.isfile(os.path.join(tdir, n))
             for n in names)
    if not ok:
        v.append("C15")
        evidence["C15"] = sorted(names)

    v.sort(key=lambda c: int(c[1:]))
    return ("violations" if v else "compliant"), v, evidence


def main():
    svcs = sorted(d for d in os.listdir(SERVICES) if d.startswith("svc-"))
    for name in svcs:
        status, viol, ev = check(name)
        print("%s %-13s %s" % (name, status, " ".join(viol)))
        if ev:
            print("    " + json.dumps(ev, sort_keys=True))


if __name__ == "__main__":
    main()
